import {readdirSync,readFileSync,existsSync,mkdirSync,writeFileSync} from 'node:fs';
import {spawnSync} from 'node:child_process';
import path from 'node:path';
import {aggregateScores,allRealScores,rescoreRun} from '../../../scripts/eval/p2/rescore.ts';
import {readEvidence,publicEvidence,sha256} from '../../../scripts/eval/p2/artifacts.ts';
const root='story/testing/runs/P2R',decisionPath=root+'/P2R-DECISIONS/20261031-one-chap-one-edit/decision.json';
const decision=JSON.parse(readFileSync(decisionPath,'utf8')),freeze=decision.freeze;
const git=(...args)=>{const r=spawnSync('git',['--no-optional-locks',...args],{encoding:'utf8',windowsHide:true});if(r.status!==0)throw Error('Git unavailable');return r.stdout.trim();};
if(git('diff','--name-only',freeze,'HEAD','--','.',':(exclude)story/testing/runs')||git('status','--porcelain=v1','--untracked-files=all','--','.',':(exclude)story/testing/runs'))throw Error('Frozen source changed');
const selected=[];
for(const [suite,count] of Object.entries(decision.scope)){
 const candidates=readdirSync(root+'/'+suite).flatMap(id=>{
  const folder=`${root}/${suite}/${id}`,file=folder+'/run-manifest.json';if(!existsSync(file))return[];
  const m=JSON.parse(readFileSync(file,'utf8'));
  return m.repositoryCommit===freeze&&m.split==='acceptance'?[{folder,m}]:[];
 });
 for(let rep=1;rep<=count;rep++){
  const matches=candidates.filter(x=>x.m.repetition===rep);if(matches.length!==1)throw Error(`Need exactly one ${suite} repetition ${rep}`);
  const {folder,m}=matches[0];
  if(m.dirty||m.stage!=='P2R'||m.phase!=='E13'||m.smoke||m.selectedCaseId||m.comparisonSetting||m.status==='running')throw Error('Ineligible selected run '+folder);
  if(suite==='P2-CHAP'&&m.runId!==decision.qualityChapRun)throw Error('Wrong CHAP selection');
  if(suite==='P2-EDIT'&&m.runId!==decision.qualityEditRun)throw Error('Wrong EDIT selection');
  const rows=readEvidence(folder,true),ids=rows.find(x=>x.type==='meta').expectedCaseIds;
  const type=suite==='P2-EDIT'?'edit_result':suite==='P2-KEEP'?'keeper_result':'opening_result';
  const outcomes=rows.filter(x=>x.type===type);
  if(outcomes.length!==ids.length||ids.some(id=>outcomes.filter(x=>x.caseId===id).length!==1))throw Error('Not all selected cases attempted '+folder);
  const rescored=rescoreRun(folder);if(!rescored.equal)throw Error('Metrics differ; inspect judgments or source before finalization: '+folder);
  selected.push({folder,runId:m.runId,suiteId:suite,repetition:rep,status:m.status,attemptedCases:ids.length,caseFailures:m.caseFailures??[],repositoryCommit:m.repositoryCommit,metricsSha256:sha256(readFileSync(folder+'/metrics.json')),manifestSha256:sha256(readFileSync(folder+'/run-manifest.json')),metrics:rescored.metrics.metrics,executionComplete:m.status==='measured_pending_gates'&&!m.caseFailures?.length});
 }
}
const quality=aggregateScores(selected,'p2r-24@1'),hard=allRealScores(root,freeze);
const chap=selected.find(x=>x.suiteId==='P2-CHAP');
const parameterRuns=selected.flatMap(x=>x.metrics.filter(m=>m.id==='T01').map(m=>({runId:x.runId,repetition:x.repetition,n:m.n,firstSuccesses:m.successes,afterRepair:m.afterRepairUsability,failureCategories:m.failureCategories})));
if(parameterRuns.some(x=>!x.afterRepair||x.afterRepair.n!==x.n||!Number.isInteger(x.afterRepair.successes)))throw Error('Parameter repair accounting missing');
const repairByRepeat=[1,2].map(rep=>{const rows=parameterRuns.filter(x=>x.repetition===rep);const n=rows.reduce((s,x)=>s+x.afterRepair.n,0),successes=rows.reduce((s,x)=>s+x.afterRepair.successes,0);return{repetition:rep,n,successes,value:n?successes/n:null};});
const parameterUsability={usedForGate:false,runs:parameterRuns,perRepetition:repairByRepeat,mean:repairByRepeat.every(x=>x.value!==null)?repairByRepeat.reduce((s,x)=>s+x.value,0)/2:null};
const singleRoundObservations=quality.metrics.filter(m=>['W01','W02','W05','E01'].includes(m.id)).map(m=>({id:m.id,n:m.n,counts:m.counts,threshold:m.threshold,minimum:m.minimum,originalTwoRepetitionValue:m.value,originalStatus:m.status}));
const result={schema:'story/author-scoped-acceptance@1',status:'program_measurements_pending_judgments',repositoryCommit:freeze,evidenceHead:git('rev-parse','HEAD'),decisionPath,decisionSha256:sha256(readFileSync(decisionPath)),selectedRuns:selected.map(({metrics,...x})=>x),quality,allReal:hard,parameterUsability,singleChapObservations:chap.metrics.filter(x=>['W01','W02'].includes(x.id)),singleRoundObservations,notes:['Selection follows the explicit author scope: OPEN2 CHAP1 KEEP2 EDIT1. No performance-based run selection.','Cancelled CHAP2 and EDIT2 are excluded from quality, included in all-real hard gates, fees and raw rescore.','The existing aggregate API retains null where a second repetition is absent. Single-round counts are reported separately; no missing value or sample minimum is waived.','Manual gates remain pending until qualified judgments and required author spotchecks are delivered.','executionComplete preserves the existing API flag; caseFailures remain in all selected denominators.']};
const destination=process.argv[2];
if(destination){
 if(!path.resolve(destination).startsWith(path.resolve(root)+path.sep))throw Error('Evidence destination outside P2R');
 mkdirSync(destination,{recursive:true});
 const text=JSON.stringify(result,null,2)+'\n';publicEvidence(text);writeFileSync(path.join(destination,'summary.json'),text,{flag:'wx'});
 const source=readFileSync(import.meta.filename,'utf8');
 const recipe=JSON.stringify({schema:'story/reproduction-source@1',scriptPath:'story/testing/exec/temp/p2r-author-scope-summary.mjs',sourceSha256:sha256(source),source,evidenceHead:result.evidenceHead,instructions:'Restore this temporary script at scriptPath and run node with no destination argument to print the same API calculation. Use the recorded evidenceHead for the original metric/judgment state. The frozen rescore module remains the scorer; this script only selects the explicit author scope.'},null,2)+'\n';
 publicEvidence(recipe);writeFileSync(path.join(destination,'reproduction.json'),recipe,{flag:'wx'});
}
console.log(JSON.stringify({selected:selected.map(x=>({suite:x.suiteId,run:x.runId,status:x.status,cases:x.attemptedCases})),quality:quality.metrics.map(({id,n,value,passed,status,perRepetition})=>({id,n,value,passed,status,perRepetition})),allReal:hard.metrics,singleChap:result.singleChapObservations}));
